import React, { useMemo } from 'react';
import { View, StyleSheet } from 'react-native';

const RIV_B64 = '';

let WebView: any = null;
try {
  const mod = require('react-native-webview');
  WebView = mod?.default ?? mod;
} catch (e: any) {
  console.warn('[PigAnimation] WebView unavailable:', e?.message);
}

export interface PigAnimationProps {
  accessories?: Record<string, boolean>;
  style?: object;
}

export default function PigAnimation({ accessories = {}, style }: PigAnimationProps) {
  const inputs = useMemo(() => JSON.stringify(accessories), [accessories]);

  const html = useMemo(() => `<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html, body { width:100%; height:100%; background:transparent; overflow:hidden; }
  canvas { display:block; width:100% !important; height:100% !important; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(function() {
  var b64 = '${RIV_B64}';
  var accessories = ${inputs};
  function b64ToBytes(s) {
    var bin = atob(s), arr = new Uint8Array(bin.length);
    for (var i=0;i<bin.length;i++) arr[i]=bin.charCodeAt(i);
    return arr;
  }
  var script = document.createElement('script');
  script.src = 'https://unpkg.com/@rive-app/canvas@2.25.4/rive.js';
  script.onload = function() {
    var r = new rive.Rive({
      buffer: b64ToBytes(b64).buffer,
      canvas: document.getElementById('c'),
      autoplay: true,
      stateMachines: 'Blank Script 1',
      onLoad: function() {
        r.resizeDrawingSurfaceToCanvas();
        try {
          var inputs = r.stateMachineInputs('Blank Script 1');
          if (inputs) {
            inputs.forEach(function(inp) {
              if (accessories[inp.name] !== undefined) inp.value = accessories[inp.name];
            });
          }
        } catch(e) {}
      }
    });
  };
  document.head.appendChild(script);
})();
</script>
</body>
</html>`, [inputs]);

  if (!WebView) return <View style={[styles.container, style]} />;

  return (
    <View style={[styles.container, style]}>
      <WebView
        source={{ html }}
        style={styles.webview}
        scrollEnabled={false}
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        overScrollMode="never"
        allowsInlineMediaPlayback
        mediaPlaybackRequiresUserAction={false}
        originWhitelist={['*']}
        javaScriptEnabled
        backgroundColor="transparent"
        androidLayerType="hardware"
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: 140,
    height: 140,
  },
  webview: {
    flex: 1,
    backgroundColor: 'transparent',
  },
});
